The evidence points to a single root cause. I'm excluding station-service: only 2 of its 146 `SELECT Station` spans exceed 50 ms, so its tail is too sporadic to name as a fault.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) AS n, approx_quantile(extract(epoch FROM (s.time - c.time))*1000, 0.5) AS gap_ms_p50, approx_quantile(c.duration/1e6, 0.5) AS client_ms_p50, approx_quantile(s.duration/1e6, 0.5) AS server_ms_p50 FROM abnormal_traces s JOIN abnormal_traces c ON c.span_id = s.parent_span_id AND c.trace_id = s.trace_id WHERE c.service_name = 'ts-travel-service' AND c.attr_span_kind = 'Client' AND s.service_name = 'ts-route-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Travel-service GET calls to route-service wait about 2.3 s before the request reaches route-service, which answers in about 5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, s.span_name, count(*) AS n, approx_quantile(extract(epoch FROM (s.time - c.time))*1000, 0.5) AS gap_ms_p50, approx_quantile(s.duration/1e6, 0.5) AS server_ms_p50 FROM abnormal_traces s JOIN abnormal_traces c ON c.span_id = s.parent_span_id AND c.trace_id = s.trace_id WHERE s.service_name = 'ts-route-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Route-service callers other than travel-service see normal gaps of about 20 ms on the same GET path."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, approx_quantile(duration/1e6, 0.5) AS p50_ms, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-travel-service' AND attr_span_kind = 'Client' AND span_name = 'GET' GROUP BY ALL",
          "claim": "Travel-service's outbound GET client spans take about 2.3 s at p50 in the abnormal window, with no errors."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(c.duration/1e6, 0.5) AS client_ms_p50, approx_quantile(s.duration/1e6, 0.5) AS server_ms_p50 FROM abnormal_traces s JOIN abnormal_traces c ON c.span_id = s.parent_span_id AND c.trace_id = s.trace_id WHERE s.service_name = 'ts-travel-service' AND c.service_name = 'ts-route-plan-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Route-plan's calls into travel-service are slow, with travel's server spans around 2.3 s at p50 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(c.duration/1e6, 0.5) AS client_ms_p50, approx_quantile(c.duration/1e6, 0.95) AS client_ms_p95 FROM abnormal_traces s JOIN abnormal_traces c ON c.span_id = s.parent_span_id AND c.trace_id = s.trace_id WHERE s.service_name = 'ts-route-plan-service' AND c.service_name = 'ts-travel-plan-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Travel-plan's calls to route-plan take seconds (p95 several seconds) while route-plan waits on travel-service."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service', 'ts-ui-dashboard') AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Travel-plan server spans and the ui-dashboard routes that call them show multi-second p95 latency."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(c.duration/1e6, 0.5) AS client_ms_p50, approx_quantile(c.duration/1e6, 0.95) AS client_ms_p95 FROM abnormal_traces s JOIN abnormal_traces c ON c.span_id = s.parent_span_id AND c.trace_id = s.trace_id WHERE s.service_name = 'ts-travel-service' AND c.service_name = 'ts-food-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Food-service calls to travel-service take about 2.3 s at p50 because travel's route lookup is delayed."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name IN ('ts-food-service', 'ts-ui-dashboard') AND span_name LIKE '%foods%' AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Food-service food lookup server spans and the ui-dashboard food route show seconds-long p95 latency."
        }
      ]
    }
  ]
}
```

